export type Input = i8

export type Output = u8

export default function (in: Input): Output {
  return match in { _ => 11 }
}

export type Input = i16

export type Output = u8

export default function (in: Input): Output {
  return match in { _ => 11 }
}

export enum State { First, Second }

export type Input = State

export type Output = u8

export default function (in: Input): Output {
  return match in { State.First => 11, State.Second => 22, }
}

export enum State { First }

export enum Other { First }

export type Input = State

export type Output = u8

export default function (in: Input): Output {
  return match in { Other.First => 11, _ => 22 }
}

export enum State { First }

export type Input = State

export type Output = u8

export default function (in: Input): Output {
  return match in { 0 => 11, _ => 22 }
}

export type Input = { target: u8
 pattern: u16 }

export type Output = u8

export default function (in: Input): Output {
  return match in.target { in.pattern => 11, _ => 22 }
}

export type Input = { target: i32
 pattern: u32 }

export type Output = u8

export default function (in: Input): Output {
  return match in.target { in.pattern => 11, _ => 22 }
}

export type Input = bool

export type Output = u8

export default function (in: Input): Output {
  return match in { 1 => 11, _ => 22 }
}
